REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(14204, 'zhCN', '英雄的召唤：西部荒野！', '奉国王陛下之命，联盟所有身强力壮的公民都须前往西部荒野的哨兵岭向格里安·斯托曼报到。$B$B你可以从艾尔文森林向西前行抵达格里安·斯托曼处。$B$B为了联盟的荣耀与荣誉！', '向西部荒野哨兵岭的格里安·斯托曼报到。', '', '向西部荒野的格里安·斯托曼报到。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(14205, 'zhCN', '英雄的召唤：北荆棘谷！', '奉国王陛下之命，联盟所有身强力壮的公民都须前往北荆棘谷的反抗军营地向尤瓦中士报到。$B$B从暮色森林向南行进，进入丛林后沿道路向西即可抵达反抗军营地。$B$B为了联盟的荣耀与荣誉！', '向北荆棘谷反抗军营地的尤瓦中士报到。', '', '向北荆棘谷的尤瓦中士报到。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(14206, 'zhCN', '英雄的召唤：藏宝海湾！', '奉国王陛下之命，联盟所有身强力壮的公民都须前往藏宝海湾向克兰克·菲兹巴布报到。$B$B从北荆棘谷向南行进，沿道路前往这座繁华的地精港口城市藏宝海湾。克兰克·菲兹巴布就在码头附近，他正为维持荆棘谷的力量平衡而寻求协助。$B$B为了联盟的荣耀与荣誉！', '向南荆棘谷藏宝海湾的克兰克·菲兹巴布报到。', '', '向南荆棘谷藏宝海湾的克兰克·菲兹巴布报到。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(14207, 'zhCN', '英雄的召唤：诅咒之地！', '奉国王陛下之命，联盟所有身强力壮的公民都须前往守望堡向军需官朗格尔斯报到。$B$B守望堡驻军急需你前往诅咒之地施以援手！从悲伤沼泽向南行进，沿道路向东即可抵达守望堡。$B$B为了联盟的荣耀与荣誉！', '向守望堡的军需官朗格尔斯报到。', '', '向守望堡的军需官朗格尔斯报到。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(14208, 'zhCN', '英雄的召唤：暮色森林！', '奉国王陛下之命，联盟所有身强力壮的公民都须前往夜色镇向指挥官阿尔泰娅·埃伯洛克报到。$B$B沿艾尔文森林与赤脊山交界处的道路向南，即可抵达暮色森林的夜色镇。$B$B为了联盟的荣耀与荣誉！', '向暮色森林夜色镇的指挥官阿尔泰娅·埃伯洛克报到。', '', '向暮色森林夜色镇的指挥官阿尔泰娅·埃伯洛克报到。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(14209, 'zhCN', '英雄的召唤：赤脊山！', '奉国王陛下之命，联盟所有身强力壮的公民都须前往赤脊山的湖畔镇向卫兵豪维报到。$B$B从艾尔文森林边界向东进入赤脊山的三岔路口地区，即可抵达湖畔镇。$B$B为了联盟的荣耀与荣誉！', '向赤脊山湖畔镇的卫兵豪维报到。', '', '向赤脊山湖畔镇的卫兵豪维报到。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(14210, 'zhCN', '英雄的召唤：燃烧平原！', '奉国王陛下之命，联盟所有身强力壮的公民都须前往燃烧平原的摩根岗哨向奥拉留斯报到。$B$B我们急需你的援助来终结黑石兽人的威胁！你可以从灼热峡谷向南穿越黑石山抵达燃烧平原。$B$B为了联盟的荣耀与荣誉！', '向燃烧平原摩根岗哨的奥拉留斯报到。', '', '向燃烧平原摩根岗哨的奥拉留斯报到。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(14211, 'zhCN', '英雄的召唤：灼热峡谷！', '奉国王陛下之命，联盟所有身强力壮的公民都须前往灼热峡谷的瑟银哨塔向汉瑟尔·重拳报到。$B$B重拳报告说，灼热峡谷的黑铁矮人似乎正在准备进攻。你的职责是尽可能查清他们的阴谋并加以阻止。你可以沿荒芜之地向西的道路抵达灼热峡谷。$B$B为了联盟的荣耀与荣誉！', '向灼热峡谷瑟银哨塔的汉瑟尔·重拳报到。', '', '向灼热峡谷瑟银哨塔的汉瑟尔·重拳报到。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(14212, 'zhCN', '英雄的召唤：洛克莫丹！', '奉国王陛下之命，联盟所有身强力壮的公民都须前往洛克莫丹的塞尔萨玛向镇长埃罗恩·钝鼻报到。$B$B狗头人与石腭怪再度猖獗，山地兵力捉襟见肘，急需增援！从丹莫罗东部穿过南门关向东行进即可抵达塞尔萨玛。$B$B为了联盟的荣耀与荣誉！', '向洛克莫丹塞尔萨玛的镇长埃罗恩·钝鼻报到。', '', '向洛克莫丹塞尔萨玛的镇长埃罗恩·钝鼻报到。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(14213, 'zhCN', '英雄的召唤：湿地！', '奉国王陛下之命，联盟所有身强力壮的公民都须前往米奈希尔港向瓦斯塔格·铁腭报到。$B$B湿地已遍布野兽、兽人劫掠者与凶残的豺狼人！要抵达湿地，你必须从洛克莫丹向北穿越矮人要塞丹奥加兹。$B$B为了联盟的荣耀与荣誉！', '向湿地米奈希尔港的瓦斯塔格·铁腭报到。', '', '向湿地米奈希尔港的瓦斯塔格·铁腭报到。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(14214, 'zhCN', '英雄的召唤：阿拉希高地！', '奉国王陛下之命，联盟所有身强力壮的公民都须前往避难谷地向尼艾丝队长报到。$B$B古老的激流堡必须重拾荣耀！食人魔与匪徒玷污它的街道已经太久了。从湿地向北跨越萨多尔大桥即可抵达阿拉希，沿路前往避难谷地向队长报到。$B$B为了联盟的荣耀与荣誉！', '向阿拉希高地避难谷地的尼艾丝队长报到。', '', '向阿拉希高地避难谷地的尼艾丝队长报到。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(14215, 'zhCN', '英雄的召唤：希尔斯布莱德丘陵！', '奉国王陛下之命，联盟所有身强力壮的公民都须前往南海镇向治安官雷德帕斯报到。$B$B自银松森林繁忙的商路向南，穿过希尔斯布莱德起伏的田野，前往联盟设防的哨站南海镇。雷德帕斯及其部下正警惕着日益频繁的部落入侵与肆虐该地的黑暗势力。$B$B洛丹伦这一要地需要你的勇气与力量来扭转战局。$B$B为了联盟的荣耀与荣誉！', '向希尔斯布莱德丘陵南海镇的治安官雷德帕斯报到。', '', '向希尔斯布莱德丘陵南海镇的治安官雷德帕斯报到。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(14216, 'zhCN', '英雄的召唤：辛特兰！', '奉国王陛下之命，联盟所有身强力壮的公民都须前往鹰巢山向狮鹫管理员沙拉克·鹰斧报到。$B$B我们联盟的新兄弟需要你的帮助，抵御危及他们家园的威胁。从阿拉希高地向北穿越矮人山口，沿道路向西北即可抵达鹰巢山。$B$B为了联盟的荣耀与荣誉！', '向辛特兰鹰巢山的狮鹫管理员沙拉克·鹰斧报到。', '', '向辛特兰鹰巢山的狮鹫管理员沙拉克·鹰斧报到。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(14217, 'zhCN', '英雄的召唤：希尔斯布莱德丘陵！', '奉国王陛下之命，联盟所有身强力壮的公民都须前往南海镇向治安官雷德帕斯报到。$B$B自银松森林繁忙的商路向南，穿过希尔斯布莱德起伏的田野，前往联盟设防的哨站南海镇。雷德帕斯及其部下正警惕着日益频繁的部落入侵与肆虐该地的黑暗势力。$B$B洛丹伦这一要地需要你的勇气与力量来扭转战局。$B$B为了联盟的荣耀与荣誉！', '向希尔斯布莱德丘陵南海镇的治安官雷德帕斯报到。', '', '向希尔斯布莱德丘陵南海镇的治安官雷德帕斯报到。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(14218, 'zhCN', '英雄的召唤：西瘟疫之地！', '奉国王陛下之命，联盟所有身强力壮的公民都须前往西瘟疫之地向指挥官阿什拉姆·瓦罗菲斯特报到。我们需要你的帮助击退天灾军团并夺回失陷的安多哈尔。$B$B要抵达寒风营地，需向北穿过希尔斯布莱德丘陵，沿道路前往寒风营地。$B$B为了联盟的荣耀与荣誉！', '向西瘟疫之地寒风营地的指挥官阿什拉姆·瓦罗菲斯特报到。', '', '向西瘟疫之地寒风营地的指挥官阿什拉姆·瓦罗菲斯特报到。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(14219, 'zhCN', '英雄的召唤：东瘟疫之地！', '奉国王陛下之命，联盟所有身强力壮的公民都须前往东瘟疫之地向大法师安吉拉·杜萨图斯报到。银色北伐军需要你的帮助，从天灾军团的魔掌中夺回东瘟疫之地。$B$B要找到东瘟疫之地圣光之愿礼拜堂的安吉拉·杜萨图斯，需向东北穿过科林路口抵达礼拜堂，那是荒芜中的一处圣所。$B$B为了联盟的荣耀与荣誉！', '向东瘟疫之地圣光之愿礼拜堂的大法师安吉拉·杜萨图斯报到。', '', '向东瘟疫之地圣光之愿礼拜堂的大法师安吉拉·杜萨图斯报到。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(14220, 'zhCN', '英雄的召唤：黑海岸！', '奉国王陛下之命，联盟所有身强力壮的公民都须前往黑海岸向戈沙拉·夜语报到。$B$B自灰谷沿海岸道路向北，直至抵达宁静而古老的黑海岸。坐落于海岸边的奥伯丁是联盟在这一地区的立足点。奥伯丁的居民呼吁你的援助，以守护这片土地的美丽与平衡。$B$B为了联盟的荣耀与荣誉！', '向黑海岸奥伯丁的戈沙拉·夜语报到。', '', '向黑海岸奥伯丁的戈沙拉·夜语报到。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(14221, 'zhCN', '英雄的召唤：冬泉谷！', '奉国王陛下之命，联盟所有身强力壮的公民都须前往冬泉谷向哈鲁·维格索斯报到。$B$B他需要你的帮助来消除冬泉熊怪的威胁。要抵达冬泉谷，你必须从费伍德森林北部向东穿越木喉要塞。$B$B为了联盟的荣耀与荣誉！', '向冬泉谷永望镇的哈鲁·维格索斯报到。', '', '向冬泉谷永望镇的哈鲁·维格索斯报到。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(14222, 'zhCN', '英雄的召唤：灰谷！', '奉国王陛下之命，联盟所有身强力壮的公民都须前往灰谷向辛德瑞尔·速火报到。$B$B绝不能坐视部落在灰谷的侵略行径！我们需要你的帮助击退入侵者、恢复这片神圣森林。从黑海岸的暮光谷向南即可抵达灰谷森林。$B$B为了联盟的荣耀与荣誉！', '向灰谷阿斯特兰纳的辛德瑞尔·速火报到。', '', '向灰谷阿斯特兰纳的辛德瑞尔·速火报到。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(14223, 'zhCN', '英雄的召唤：凄凉之地！', '奉国王陛下之命，联盟所有身强力壮的公民都须前往凄凉之地向麦尔金斯下士报到。$B$B尼耶尔前哨的勇敢士兵正遭受恶魔与部落大军的围困，他们需要你的帮助。要抵达凄凉之地，需从石爪山脉的焦痕谷沿道路向南行进。$B$B为了联盟的荣耀与荣誉！', '向凄凉之地尼耶尔前哨的麦尔金斯下士报到。', '', '向凄凉之地尼耶尔前哨的麦尔金斯下士报到。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(14224, 'zhCN', '英雄的召唤：费拉斯！', '奉国王陛下之命，联盟所有身强力壮的公民都须前往费拉斯向珊蒂斯·羽月报到。$B$B联盟需要你的帮助来战胜我们的敌人——部落与恐怖图腾氏族。你可以从凄凉之地向南进入费拉斯，找到珊蒂斯·羽月。$B$B为了联盟的荣耀与荣誉！', '向费拉斯羽月要塞的珊蒂斯·羽月报到。', '', '向费拉斯羽月要塞的珊蒂斯·羽月报到。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(14225, 'zhCN', '英雄的召唤：尘泥沼泽！', '奉国王陛下之命，联盟所有身强力壮的公民都须前往尘泥沼泽向艾登中尉报到。$B$B你必须协助艾登中尉查明塞拉摩城内外的威胁。你可以从米奈希尔乘船，或从南贫瘠之地穿过沼泽抵达塞拉摩岛。$B$B为了联盟的荣耀与荣誉！', '向尘泥沼泽塞拉摩岛的艾登中尉报到。', '', '向尘泥沼泽塞拉摩岛的艾登中尉报到。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(14226, 'zhCN', '英雄的召唤：塔纳利斯！', '奉国王陛下之命，联盟所有身强力壮的公民都须前往塔纳利斯向首席工程师沙克斯·比格维兹报到。$B$B联盟需要你的帮助，从当地男爵手中争得让步，并获取该地区珍贵的资源。你可以从千针石林的闪光平原向南抵达加基森。$B$B为了联盟的荣耀与荣誉！', '向塔纳利斯加基森的首席工程师沙克斯·比格维兹报到。', '', '向塔纳利斯加基森的首席工程师沙克斯·比格维兹报到。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(14227, 'zhCN', '英雄的召唤：安戈洛环形山！', '奉国王陛下之命，联盟所有身强力壮的公民都须前往安戈洛环形山的马绍尔营地向威利德·马绍尔报到。$B$B联盟需要你为马绍尔远征队提供支持，协助他们揭开安戈洛环形山远古野兽、独特植被与强大水晶的秘密。你可以从塔纳利斯西部出发，沿道路一直抵达马绍尔哨站。$B$B为了联盟的荣耀与荣誉！', '向安戈洛环形山马绍尔营地的威利德·马绍尔报到。', '', '向安戈洛环形山马绍尔营地的威利德·马绍尔报到。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(14228, 'zhCN', '英雄的召唤：希利苏斯！', '奉国王陛下之命，联盟所有身强力壮的公民都须前往希利苏斯向唤风者梅恩·长角报到。$B$B我们的塞纳里奥议会盟友需要你的协助，以击退暮光之锤的猛攻。你可以从安戈洛环形山沿西北道路抵达希利苏斯。$B$B为了联盟的荣耀与荣誉！', '向希利苏斯塞纳里奥要塞的唤风者梅恩·长角报到。', '', '向希利苏斯塞纳里奥要塞的唤风者梅恩·长角报到。', NULL);
