(14230, 'zhCN', '大酋长的命令：费伍德森林！', '特此命令部落所有身体健全的成员前往费伍德森林向格雷塔·苔蹄报到。$B$B塞纳里奥议会需要你的帮助，从恶魔与其他堕落生物的掌控中夺回费伍德！要抵达翡翠圣地，需从灰谷向北沿道路前行直至圣地。$B$B命运在召唤！', '向费伍德森林翡翠圣地的格雷塔·苔蹄报到。', '', '向费伍德森林翡翠圣地的格雷塔·苔蹄报到。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(14231, 'zhCN', '大酋长的命令：灰谷！', '特此命令部落所有身体健全的成员前往灰谷向米苏瓦报到。$B$B她需要你的援助，抵御步步逼近的暗夜精灵及其盟友、保卫我们的土地。要抵达灰谷，你必须从北贫瘠之地的十字路口沿黄金之路向北行进。$B$B命运在召唤！', '向灰谷佐拉姆加前哨的米苏瓦报到。', '', '向灰谷佐拉姆加前哨的米苏瓦报到。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(14232, 'zhCN', '大酋长的命令：贫瘠之地！', '特此命令部落所有身体健全的成员前往贫瘠之地的十字路口向瑟格拉·黑棘报到。$B$B她需要你的协助，守卫这一重要哨站，抵御野猪人、半人马与联盟军队的威胁。要抵达十字路口，可从杜隆塔尔向南或从莫高雷向北行进。$B$B命运在召唤！', '向贫瘠之地十字路口的瑟格拉·黑棘报到。', '', '向贫瘠之地十字路口的瑟格拉·黑棘报到。', NULL);
