(14244, 'zhCN', '大酋长的命令：阿拉希高地！', '特此命令部落所有身体健全的成员前往阿拉希高地的落锤镇向托尔甘报到。$B$B激流堡的军队躁动不安，辛迪加的背叛威胁着我们的行动。我们需要你的勇气来稳固阵地、粉碎这些敌人。$B$B要抵达阿拉希高地，可从希尔斯布莱德丘陵向东，沿道路越过索拉丁之墙。$B$B命运在召唤！', '向阿拉希高地落锤镇的托尔甘报到。', '', '向阿拉希高地落锤镇的托尔甘报到。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(14245, 'zhCN', '大酋长的命令：辛特兰！', '特此命令部落所有身体健全的成员前往辛特兰的雷文塔斯克村向莫吉克报到。$B$B凶残嗜血的邪枝巨魔加紧了对我们盟友的袭击，并玷污了辛特兰的神圣土地。他们的黑暗仪式与无休止的侵略再也不能容忍。我们必须愤怒反击，清除这片土地上的腐化。$B$B要抵达雷文塔斯克村，可从希尔斯布莱德丘陵东部的山口进入辛特兰，再前往东海岸。$B$B命运在召唤！', '向辛特兰雷文塔斯克村的奥索·莫吉克报到。', '', '向辛特兰雷文塔斯克村的奥索·莫吉克报到。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(14246, 'zhCN', '大酋长的命令：西瘟疫之地！', '特此命令部落所有身体健全的成员前往西瘟疫之地的壁垒向高级执行官德灵顿报到。我们需要你的帮助击退天灾军团并夺回失陷的安多哈尔。$B$B要抵达壁垒，需从幽暗城向南穿过提瑞斯法林地，沿道路前往东部边境，壁垒就守卫在那里。$B$B命运在召唤！', '向西瘟疫之地壁垒的高级执行官德灵顿报到。', '', '向西瘟疫之地壁垒的高级执行官德灵顿报到。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(14247, 'zhCN', '大酋长的命令：东瘟疫之地！', '特此命令部落所有身体健全的成员前往东瘟疫之地向大法师安吉拉·杜萨图斯报到。银色北伐军需要你的帮助，从天灾军团的魔掌中夺回东瘟疫之地。$B$B要找到东瘟疫之地圣光之愿礼拜堂的安吉拉·杜萨图斯，需向东北穿过科林路口抵达礼拜堂，那是荒芜中的一处圣所。$B$B命运在召唤！', '向东瘟疫之地圣光之愿礼拜堂的大法师安吉拉·杜萨图斯报到。', '', '向东瘟疫之地圣光之愿礼拜堂的大法师安吉拉·杜萨图斯报到。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(14248, 'zhCN', '大酋长的命令：灼热峡谷！', '特此命令部落所有身体健全的成员前往灼热峡谷的瑟银哨塔向汉瑟尔·重拳报到。$B$B重拳报告说，灼热峡谷的黑铁矮人似乎正在准备进攻。你的职责是尽可能查清他们的阴谋并加以阻止。你可以沿荒芜之地向西的道路抵达灼热峡谷。$B$B命运在召唤！', '向灼热峡谷瑟银哨塔的汉瑟尔·重拳报到。', '', '向灼热峡谷瑟银哨塔的汉瑟尔·重拳报到。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(14249, 'zhCN', '大酋长的命令：荒芜之地！', '特此命令部落所有身体健全的成员前往荒芜之地的卡加斯向高恩报到。$B$B有人发现黑铁氏族的盟友暗炉矮人正在荒芜之地集结兵力。他们的存在威胁到我们盟友的安全与该地区的稳定。你的任务是追猎并消灭这些暗炉矮人，确保他们的计划在发难前就被挫败。$B$B可从灼热峡谷向东抵达荒芜之地。卡加斯作为我们在该地区的据点，将作为你的行动基地。$B$B命运在召唤！', '向荒芜之地卡加斯的高恩报到。', '', '向荒芜之地卡加斯的高恩报到。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(14250, 'zhCN', '大酋长的命令：悲伤沼泽！', '特此命令部落所有身体健全的成员前往悲伤沼泽的斯通纳德向达尔报到。$B$B可从诅咒之地向南抵达悲伤沼泽。斯通纳德作为我们在该地区的哨站，将作为你的行动基地。$B$B命运在召唤！', '向悲伤沼泽斯通纳德的达尔报到。', '', '向悲伤沼泽斯通纳德的达尔报到。', NULL);
