(14251, 'zhCN', '大酋长的命令：北荆棘谷！', '特此命令部落所有身体健全的成员前往格罗姆高营地阿格罗戈什处报到。指挥官需要你的援助，确保补给线畅通，不受当地居民与麻烦的联盟干扰。$B$B要抵达格罗姆高，你可以乘坐奥格瑞玛城外塔楼或幽暗城附近的飞艇。$B$B命运在召唤！', '向北荆棘谷格罗姆高营地的指挥官阿格罗戈什报到。', '', '向北荆棘谷格罗姆高营地的指挥官阿格罗戈什报到。', NULL);
REPLACE INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `VerifiedBuild`) VALUES
(14252, 'zhCN', '大酋长的命令：藏宝海湾！', '特此命令部落所有身体健全的成员前往藏宝海湾向克兰克·菲兹巴布报到。$B$B从北荆棘谷向南行进，沿道路前往这座繁华的地精港口城市藏宝海湾。克兰克·菲兹巴布就在码头附近，他正为维持荆棘谷的力量平衡而寻求协助。$B$B命运在召唤！', '向南荆棘谷藏宝海湾的克兰克·菲兹巴布报到。', '', '向南荆棘谷藏宝海湾的克兰克·菲兹巴布报到。', NULL);
